import{_ as a,o as r,c as o,a2 as t}from"./chunks/framework.CZqXuAiL.js";const h=JSON.parse('{"title":"Addons Guide — Glacier Pack","description":"What each of the 24 Glacier Pack addons does, where it lives in the hub, what users see on the client side, and practical usage notes.","frontmatter":{"title":"Addons Guide — Glacier Pack","description":"What each of the 24 Glacier Pack addons does, where it lives in the hub, what users see on the client side, and practical usage notes.","outline":"deep"},"headers":[],"relativePath":"glacier-pack/user-guide/addons.md","filePath":"glacier-pack/user-guide/addons.md","lastUpdated":null}'),s={name:"glacier-pack/user-guide/addons.md"};function n(i,e,l,d,c,u){return r(),o("div",null,[...e[0]||(e[0]=[t('<h1 id="addons-guide" tabindex="-1">Addons Guide <a class="header-anchor" href="#addons-guide" aria-label="Permalink to &quot;Addons Guide&quot;">​</a></h1><p>One compact brief per addon: what it does, where it lives in the hub, its client-facing surface, and the things worth knowing before you rely on it. Settings and defaults for each addon are in the <a href="./../configuration/reference">Configuration Reference</a>.</p><hr><h2 id="basic-pack" tabindex="-1">Basic pack <a class="header-anchor" href="#basic-pack" aria-label="Permalink to &quot;Basic pack&quot;">​</a></h2><h3 id="recycle-bin" tabindex="-1">Recycle Bin <a class="header-anchor" href="#recycle-bin" aria-label="Permalink to &quot;Recycle Bin&quot;">​</a></h3><p>Deleted files move to a hidden <code>/.trash</code> folder instead of vanishing, with per-server quotas, per-egg retention windows, collision-safe restore (<code>name (restored)</code>), and an hourly purge.</p><ul><li><strong>Hub:</strong> <code>?a=recycle-bin</code> — single pane (settings, storage overview, top servers, per-egg overrides).</li><li><strong>Client surface:</strong> server file manager — a Recycle Bin toolbar button plus restore / empty-bin / permanent-delete flows, gated by the <code>trashbinpro.access</code> subuser permission.</li><li>Trashed files count against the server&#39;s real disk quota — set a capacity on shared nodes (<code>0</code> = unlimited).</li><li><strong>Requires a frontend rebuild</strong> (<code>yarn build:production</code>) after install and again after uninstall; re-run <code>install.sh</code> after panel updates.</li></ul><h3 id="url-download" tabindex="-1">URL Download <a class="header-anchor" href="#url-download" aria-label="Permalink to &quot;URL Download&quot;">​</a></h3><p>Users paste one or more remote URLs into a guided file-manager modal and the panel fetches the files straight into the server through Wings — no SFTP round-trip.</p><ul><li><strong>Hub:</strong> <code>?a=url-download</code> — single settings pane (policy, throughput, client experience, safeguards, history).</li><li><strong>Client surface:</strong> server file manager — a toolbar button (label configurable) with a step-by-step modal, progress popup or floating deck, and per-user URL memory chips.</li><li>Pre-flight checks include scheme/extension allow-lists and a remote HEAD probe; conflicts auto-rename, overwrite or skip per file.</li><li>Transfers run on the node via the native <code>files/pull</code> endpoint — a healthy panel↔Wings link is required.</li></ul><h3 id="config-editor" tabindex="-1">Config Editor <a class="header-anchor" href="#config-editor" aria-label="Permalink to &quot;Config Editor&quot;">​</a></h3><p>Edit the panel&#39;s <code>.env</code> safely from the browser: structured rows grouped by prefix, secret masking, validation, review-before-save, and atomic writes with 10 rotating backups.</p><ul><li><strong>Hub:</strong> <code>?a=config-editor</code> — sub-tabs <strong>Editor</strong> and <strong>Raw file</strong>.</li><li><strong>Client surface:</strong> none (admin-only tool).</li><li>Never edit <code>APP_KEY</code> — encrypted panel data becomes unreadable. Changing session/cache keys logs everyone out.</li><li>Requires the <code>.env</code> to be writable by the webserver user; otherwise the pane is read-only.</li></ul><h3 id="console-log-share" tabindex="-1">Console Log Share <a class="header-anchor" href="#console-log-share" aria-label="Permalink to &quot;Console Log Share&quot;">​</a></h3><p>Copy-to-clipboard and one-click upload of the server console log to an mclogs-compatible paste service, proxied through the panel.</p><ul><li><strong>Hub:</strong> <code>?a=console-log-share</code> — single settings pane (endpoint, enable, placement) with a reset action.</li><li><strong>Client surface:</strong> server console page — a Copy Log / Share Log bar above or below the terminal, gated by <code>websocket.connect</code>.</li><li>ANSI codes are stripped server-side; oversized logs are trimmed to the configured cap.</li><li>The paste endpoint must be the mclogs-compatible <strong>API</strong> URL (default <code>https://api.mclo.gs/1/log</code>).</li></ul><h3 id="login-activity" tabindex="-1">Login Activity <a class="header-anchor" href="#login-activity" aria-label="Permalink to &quot;Login Activity&quot;">​</a></h3><p>Records every successful sign-in (password, 2FA, remember-me) with IP, user agent and timestamp.</p><ul><li><strong>Hub:</strong> <code>?a=login-activity</code> — single read-only pane with user and date-range filters.</li><li><strong>Client surface:</strong> a Login Activity section on the account page (<code>/account</code>) showing each user their own history with browser/OS summaries.</li><li>Recording failures never block sign-in; history is kept on uninstall unless you pass <code>--drop-table</code>.</li><li>Users only ever see their own records through the client API.</li></ul><h3 id="move-files" tabindex="-1">Move Files <a class="header-anchor" href="#move-files" aria-label="Permalink to &quot;Move Files&quot;">​</a></h3><p>Upgrades the file manager&#39;s move/copy UX: a browsable destination tree, copy-to-anywhere, overwrite confirmation, progress feedback, rename-while-moving and create-folder-in-dialog.</p><ul><li><strong>Hub:</strong> <code>?a=move-files</code> — informational card only; the addon has no settings.</li><li><strong>Client surface:</strong> server file manager move dialog and per-file Copy action.</li><li>Frontend-only — no routes, tables or backend; all operations go through the panel&#39;s existing client API with the user&#39;s own permissions.</li><li>Hard-refresh the Files page after install; re-run <code>install.sh</code> after panel updates overwrite the patched template.</li></ul><h3 id="node-status" tabindex="-1">Node Status <a class="header-anchor" href="#node-status" aria-label="Permalink to &quot;Node Status&quot;">​</a></h3><p>Per-server uptime tracking: status banners, daily uptime strips, incident timelines with reasons, node health views, and admin-posted service updates with optional countdowns.</p><ul><li><strong>Hub:</strong> <code>?a=node-status</code> — sub-tabs <strong>Overview</strong> (settings + per-node overrides) and <strong>Service Updates</strong>.</li><li><strong>Client surface:</strong> two server sub-navigation tabs — <strong>Uptime</strong> and <strong>Service updates</strong> — gated by the <code>uptime.read</code> subuser permission.</li><li>The panel polls Wings on a schedule — the standard panel cron must be running; no agent on nodes.</li><li>Real node names are hidden from users unless you enable them; tracking can be toggled per node.</li></ul><h3 id="panel-logs" tabindex="-1">Panel Logs <a class="header-anchor" href="#panel-logs" aria-label="Permalink to &quot;Panel Logs&quot;">​</a></h3><p>A live view of the panel&#39;s own <code>storage/logs/*.log</code> files without SSH: tail viewer, level filters with counters, auto-refresh, download, clear and delete.</p><ul><li><strong>Hub:</strong> <code>?a=panel-logs</code> — <strong>Log files</strong> tab plus a viewer tab that opens per file.</li><li><strong>Client surface:</strong> none (admin-only tool).</li><li>Stack traces stay grouped; the viewer pauses when the tab is hidden and recovers from log rotation on its own.</li><li>Root-admin only, strict filename validation; the panel recreates a cleared log automatically.</li></ul><h3 id="resource-alerts" tabindex="-1">Resource Alerts <a class="header-anchor" href="#resource-alerts" aria-label="Permalink to &quot;Resource Alerts&quot;">​</a></h3><p>Watches CPU, memory, disk and network throughput of every server and notifies you the moment a server crosses a threshold — by email and optional Discord/Slack webhooks.</p><ul><li><strong>Hub:</strong> <code>?a=resource-alerts</code> — sub-tabs <strong>Overview</strong>, <strong>Rules</strong>, <strong>History</strong>, <strong>Settings</strong>.</li><li><strong>Client surface:</strong> none; delivery is email + webhooks.</li><li>Rules layer global → per-node → per-server (most specific wins) and fire only after N consecutive 1-minute samples — no flapping, with automatic recovery notices.</li><li>Requires the panel cron (one sample per minute); use <strong>Send Test Alert</strong> after configuring channels.</li></ul><hr><h2 id="advanced-pack" tabindex="-1">Advanced pack <a class="header-anchor" href="#advanced-pack" aria-label="Permalink to &quot;Advanced pack&quot;">​</a></h2><h3 id="backup-pro" tabindex="-1">Backup Pro <a class="header-anchor" href="#backup-pro" aria-label="Permalink to &quot;Backup Pro&quot;">​</a></h3><p>Scheduled server backups to any S3-compatible storage (AWS, Cloudflare R2, Backblaze B2, Wasabi, MinIO, Spaces) using the panel&#39;s native backup pipeline, with retention policies, offload, restore and notifications.</p><ul><li><strong>Hub:</strong> <code>?a=backup-pro</code> — sub-tabs <strong>Overview</strong>, <strong>Destinations</strong>, <strong>Backup Rules</strong>, <strong>Backups</strong>, <strong>Archives</strong>, <strong>Activity</strong>, <strong>Settings</strong>.</li><li><strong>Client surface:</strong> server backups page — a &quot;protected by S3&quot; banner, per-backup cloud badges, optional click-to-sync, and (when enabled) cloud download/restore.</li><li>Rules combine two modes — mirror existing backups and/or create on a schedule — against all servers, a node, or hand-picked servers; credentials are encrypted with the panel app key.</li><li>Pending uploads with a red cloud icon almost always mean the queue worker (<code>standard</code> queue) is not running.</li></ul><h3 id="database-manager" tabindex="-1">Database Manager <a class="header-anchor" href="#database-manager" aria-label="Permalink to &quot;Database Manager&quot;">​</a></h3><p>One-click <code>.sql</code> export and streamed import for panel-managed MySQL databases, straight from the server&#39;s Databases page — no phpMyAdmin, no shared credentials.</p><ul><li><strong>Hub:</strong> <code>?a=database-manager</code> — single pane (limits, toggles, recent operations log).</li><li><strong>Client surface:</strong> server Databases page — per-database Export and Import actions, gated by the <code>databasemanager.export</code> / <code>databasemanager.import</code> subuser permissions.</li><li>Exports use <code>--single-transaction</code> so InnoDB stays writable; optional wipe-before-import when you allow it.</li><li>Requires <code>mysqldump</code>/<code>mysql</code> client binaries on the panel host; raise PHP upload limits before raising the import cap.</li></ul><h3 id="mod-installer" tabindex="-1">Mod Installer <a class="header-anchor" href="#mod-installer" aria-label="Permalink to &quot;Mod Installer&quot;">​</a></h3><p>Browse, search and install Minecraft mods from Modrinth and CurseForge directly on the server page; the panel resolves the URL and Wings fetches the file into <code>/mods</code>.</p><ul><li><strong>Hub:</strong> <code>?a=mod-installer</code> — single settings pane (CurseForge key, default provider, default loader) with provider status badges.</li><li><strong>Client surface:</strong> a <strong>Mods</strong> tab on every server&#39;s navigation with loader/version filters and a versions dialog; browsing needs <code>file.read</code>, installing needs <code>file.create</code>.</li><li>Modrinth works out of the box; CurseForge unlocks once you save an API key from the CurseForge console.</li><li>Panel needs outbound HTTPS to the catalogue APIs; nodes must reach the mod CDNs.</li></ul><h3 id="modpack-installer" tabindex="-1">Modpack Installer <a class="header-anchor" href="#modpack-installer" aria-label="Permalink to &quot;Modpack Installer&quot;">​</a></h3><p>One-click Modrinth and CurseForge modpack installs from the file manager — full version lists, a confirmation screen with exact file counts, and live per-file progress.</p><ul><li><strong>Hub:</strong> <code>?a=modpack-installer</code> — single settings pane with health badges, usage counters and recent installs.</li><li><strong>Client surface:</strong> a <strong>Modpacks</strong> button in the server file manager opening the browse/install wizard, plus per-server install history.</li><li>Everything ships to the node as a single bundle pulled via the native <code>files/pull</code> endpoint and extracted via <code>files/decompress</code>; client-only mods and third-party-opt-out files are auto-skipped and listed up front.</li><li>Installs files only — egg, Docker image and startup jar are untouched; requires the PHP <code>zip</code> extension and a writable staging directory (both shown as pane badges).</li></ul><h3 id="node-stats" tabindex="-1">Node Stats <a class="header-anchor" href="#node-stats" aria-label="Permalink to &quot;Node Stats&quot;">​</a></h3><p>Fleet-wide analytics: CPU/RAM/disk/bandwidth time-series, per-node drill-downs, multi-tier historical aggregates, capacity exhaustion forecasts, top consumers, and downloadable daily/weekly/monthly reports.</p><ul><li><strong>Hub:</strong> <code>?a=node-stats</code> — sub-tabs <strong>Overview</strong>, <strong>Nodes</strong>, <strong>Capacity</strong>, <strong>Historical</strong>, <strong>Top Consumers</strong>, <strong>Reports</strong>, <strong>Settings</strong>.</li><li><strong>Client surface:</strong> none (admin-only dashboards).</li><li>Charts use a locally bundled Chart.js — zero external requests.</li><li>Needs both the panel cron <strong>and</strong> a Supervisor worker on the <code>nodeanalytics</code> queue (<code>data/install-queue-worker.sh</code> sets it up); empty dashboards mean one of the two is missing.</li></ul><h3 id="permission-manager" tabindex="-1">Permission Manager <a class="header-anchor" href="#permission-manager" aria-label="Permalink to &quot;Permission Manager&quot;">​</a></h3><p>Delegate admin work safely: staff roles, members, scoped assignments and a restricted staff area at <code>/admin/staff</code> — without ever granting <code>root_admin</code>.</p><ul><li><strong>Hub:</strong> <code>?a=permission-manager</code> — sub-tabs <strong>Overview</strong>, <strong>Roles</strong>, <strong>Members</strong>, <strong>Audit Log</strong>.</li><li><strong>Client surface:</strong> no new client pages — staff reach in-scope servers as real, auto-provisioned Pterodactyl subusers (default: console, power actions, file read), enforced natively by the panel.</li><li>Roles control which staff pages open, whether members see all or only assigned users/servers, and whether they may edit server build configuration; every write lands in the audit log.</li><li>Role deletion is refused while members are assigned; before uninstalling, remove members or run <code>php artisan permgr:sync</code> so no provisioned subusers remain.</li></ul><h3 id="player-list" tabindex="-1">Player List <a class="header-anchor" href="#player-list" aria-label="Permalink to &quot;Player List&quot;">​</a></h3><p>A live online-player card with an <code>online / max</code> badge on the server console page, self-refreshing without reloads.</p><ul><li><strong>Hub:</strong> <code>?a=player-list</code> — single settings pane (enable, protocol, timeout/cache/refresh) with a built-in host:port test tool.</li><li><strong>Client surface:</strong> server console page — a Players card beneath the terminal polling the client API at your configured interval.</li><li>UDP query returns the full list but needs <code>enable-query=true</code>; the status-ping fallback needs no setup but returns only a name sample (flagged as such).</li><li>Results are cached per server to avoid query floods; degrades quietly when a server is offline.</li></ul><h3 id="player-manager" tabindex="-1">Player Manager <a class="header-anchor" href="#player-manager" aria-label="Permalink to &quot;Player Manager&quot;">​</a></h3><p>Manage Minecraft Java players over plain RCON from the client panel: online list, kick/ban/unban, op/deop and whitelist management. Nothing is installed on the node.</p><ul><li><strong>Hub:</strong> <code>?a=player-manager</code> — single settings pane (enable, default port, timeouts) plus the stored-credentials table.</li><li><strong>Client surface:</strong> a <strong>Players</strong> page on every server&#39;s navigation, including a per-server RCON connection form (stored encrypted); viewing needs <code>websocket.connect</code>, actions need <code>control.console</code>, and every action hits the activity log.</li><li>Each server needs <code>enable-rcon=true</code>, <code>rcon.port</code> and <code>rcon.password</code> in <code>server.properties</code>, with the RCON port reachable from the panel host.</li><li>Credentials resolve per-server override → <code>RCON_PASSWORD</code>/<code>RCON_PORT</code>/<code>RCON_HOST</code> server variables → defaults.</li></ul><h3 id="plugin-installer" tabindex="-1">Plugin Installer <a class="header-anchor" href="#plugin-installer" aria-label="Permalink to &quot;Plugin Installer&quot;">​</a></h3><p>Search Modrinth, Hangar, Spiget, CurseForge and Polymart from the server page and install plugins straight into <code>/plugins</code> — with an installed-plugin library and SHA-512 update hints.</p><ul><li><strong>Hub:</strong> <code>?a=plugin-installer</code> — single settings pane (provider toggles, CurseForge key, install directory, analysis cap).</li><li><strong>Client surface:</strong> a <strong>Plugins</strong> page on every server&#39;s navigation with provider/software/version filters, per-release install buttons, and an Installed tab with one-click updates; browsing needs <code>file.read</code>, installing needs <code>file.create</code>.</li><li>Premium/external resources are marked and never pulled; CurseForge and Polymart are off by default.</li><li>Wings performs the actual downloads — nodes must reach the provider CDNs.</li></ul><h3 id="server-importer" tabindex="-1">Server Importer <a class="header-anchor" href="#server-importer" aria-label="Permalink to &quot;Server Importer&quot;">​</a></h3><p>Move servers from another Pterodactyl panel using the source&#39;s Application API: stored connections, inventory fetch, dry run with a full conflict report, execution, and one-click rollback.</p><ul><li><strong>Hub:</strong> <code>?a=server-importer</code> — sub-tabs <strong>Overview</strong> and <strong>Run report</strong>.</li><li><strong>Client surface:</strong> none (root-admin tool).</li><li>A dry run creates nothing — it reports user matches, egg matches, allocation claims and dropped environment values; claims are re-verified before execution, and rollback force-deletes everything a run created.</li><li>Needs a <code>ptla_…</code> key on the source panel with read access to servers, users, nodes, nests and eggs, and a target node with enough free allocations.</li></ul><h3 id="server-properties" tabindex="-1">Server Properties <a class="header-anchor" href="#server-properties" aria-label="Permalink to &quot;Server Properties&quot;">​</a></h3><p>A friendly, categorized <code>server.properties</code> editor for Minecraft servers: typed inputs (toggles, dropdowns, clamped numbers), per-key descriptions, live search and dirty tracking.</p><ul><li><strong>Hub:</strong> <code>?a=server-properties</code> — single settings pane (tab label, file name, allowed nests, descriptions).</li><li><strong>Client surface:</strong> a <strong>Properties</strong> tab on eligible servers (default: nest <code>1</code>, the stock Minecraft nest); reads need <code>file.read-content</code>, writes need <code>file.update</code>.</li><li>Writes go through the panel&#39;s Wings file repository — comments, blank lines and key order survive; unknown keys land under &quot;Other&quot;.</li><li>Changes apply after a server restart — Minecraft reads the file at boot.</li></ul><h3 id="staff-requests" tabindex="-1">Staff Requests <a class="header-anchor" href="#staff-requests" aria-label="Permalink to &quot;Staff Requests&quot;">​</a></h3><p>Users request server access from each other — by server ID or owner email — with owner approval, three permission presets, temporary access, blocking and a full audit trail. Approved requests create real subusers.</p><ul><li><strong>Hub:</strong> <code>?a=staff-requests</code> — single pane (access policy, limits, stats, read-only requests/grants/audit tables).</li><li><strong>Client surface:</strong> Account → Staff Requests (<code>/account/server-access</code>) plus an Access Manager shortcut on the server Users page for owners and holders of the <code>accessmanager.manage</code> permission.</li><li>Temporary access (1 hour to 30 days) is revoked automatically by the panel cron, including SFTP session invalidation.</li><li>The email flow never reveals account existence; uninstalling does not remove already-granted subusers.</li></ul><h3 id="subdomain-manager" tabindex="-1">Subdomain Manager <a class="header-anchor" href="#subdomain-manager" aria-label="Permalink to &quot;Subdomain Manager&quot;">​</a></h3><p>Self-service DNS for game servers: users create A and SRV records on the Network page, provisioned through the Cloudflare API against zones you control.</p><ul><li><strong>Hub:</strong> <code>?a=subdomain-manager</code> — sub-tabs <strong>Settings</strong>, <strong>Domains</strong>, <strong>Records</strong>.</li><li><strong>Client surface:</strong> a Subdomains card on the server Network page, gated by the <code>subdomainplus.read</code> / <code>create</code> / <code>delete</code> subuser permissions.</li><li>SRV records point at stable per-allocation hostnames that survive IP changes; records are always created unproxied.</li><li>Per domain you can restrict eggs, ban names via regex, force a target IP, and define SRV presets; keep the panel cron running for sync and orphan cleanup.</li></ul><h3 id="version-changer" tabindex="-1">Version Changer <a class="header-anchor" href="#version-changer" aria-label="Permalink to &quot;Version Changer&quot;">​</a></h3><p>Let users switch a server&#39;s Minecraft: Java Edition version from the panel — official Mojang releases, snapshots and historic builds, with automatic jar backups and optional startup-variable updates.</p><ul><li><strong>Hub:</strong> <code>?a=version-changer</code> — single settings pane plus a recent-changes table.</li><li><strong>Client surface:</strong> a Version Changer card on the server Startup page; viewing needs <code>file.read</code>, installing needs <code>file.create</code>.</li><li>Jar downloads are pinned to official Mojang hosts regardless of the manifest endpoint; the previous jar is renamed to <code>&lt;name&gt;.backup-&lt;timestamp&gt;</code> before writing.</li><li>The running process keeps the old jar until the next restart — tell users to restart after switching.</li></ul><hr><h2 id="what-s-next" tabindex="-1">What&#39;s Next? <a class="header-anchor" href="#what-s-next" aria-label="Permalink to &quot;What&#39;s Next?&quot;">​</a></h2><ul><li><strong><a href="./../configuration/reference">Configuration Reference →</a></strong> — every setting on every pane, with defaults.</li><li><strong><a href="./dashboard">The Hub Dashboard →</a></strong> — layout, sub-tabs and the save round-trip.</li></ul>',78)])])}const p=a(s,[["render",n]]);export{h as __pageData,p as default};
